#!/usr/bin/env node
// Fake Codex CLI for E2E tests. The command line matches the `@openai/codex` agent rule. Like Codex, it shows its
// activity in the terminal title (a spinner while working, "[ ! ] Action Required" while it waits) and rings the bell
// when a turn is complete; with `--status` it also reports OSC 7501 lifecycle states (recent Codex builds):
//   work → working   ask → waiting for an approval   done → turn complete (+ BEL)   quit → exit
//   anything else → a prompt: printed as "PROMPT: <text>", working for half a second, then the turn is complete.
'use strict';
const readline = require('node:readline');

const ESC = '\x1b';
const status = process.argv.includes('--status');
const SPINNER = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
let spin;
const title = (text) => process.stdout.write(`${ESC}]0;${text}\x07`);
const report = (state) => {
  if (status) process.stdout.write(`${ESC}]7501;state=${state}:app=codex${ESC}\\`);
};
const stopSpinner = () => {
  clearInterval(spin);
  spin = undefined;
};
const prompt = () => process.stdout.write('fake-codex> ');

title('fake-project');
report('idle');
process.stdout.write('Fake Codex ready\r\n');
prompt();

const rl = readline.createInterface({ input: process.stdin });
rl.on('line', (line) => {
  const cmd = line.trim();
  stopSpinner();
  if (cmd === 'work') {
    let frame = 0;
    report('working');
    title(`${SPINNER[0]} fake-project`);
    spin = setInterval(() => title(`${SPINNER[++frame % SPINNER.length]} fake-project`), 100);
    process.stdout.write('working…\r\n');
  } else if (cmd === 'ask') {
    report('blocked:kind=permission');
    title('[ ! ] Action Required | fake-project');
    process.stdout.write('Allow command? \x07\r\n');
  } else if (cmd === 'done') {
    report('done');
    title('Fake thread | fake-project');
    process.stdout.write('Turn complete\x07\r\n');
  } else if (cmd === 'quit') {
    report('clear');
    process.exit(0);
  } else if (cmd) {
    report('working');
    process.stdout.write(`PROMPT: ${cmd}\r\n`);
    setTimeout(() => {
      report('done');
      process.stdout.write('Turn complete\x07\r\n');
      prompt();
    }, 500);
    return;
  }
  prompt();
});
